# b1u3 — Work and career: practice sentences, 12 per lesson.
DRILLS = {
 "b1u3l1": [
  ("This ad is badly written; you can't understand anything.", "ประกาศนี้เขียนไม่ดีเลย อ่านแล้วไม่เข้าใจอะไรเลย", "prà-kàat níi khǐan mâi dii ləəi, àan lɛ́ɛo mâi khâo-jai à-rai ləəi"),
  ("You have to submit the documents for the application by Friday.", "ต้องส่งเอกสารสมัครงานภายในวันศุกร์", "tɔ̂ng sòng èek-kà-sǎan sà-màk-ngaan phaai-nai wan sùk"),
  ("The results of the selection will be announced next week.", "ผลการคัดเลือกจะประกาศสัปดาห์หน้า", "phǒn kaan khát-lʉ̂ak jà prà-kàat sàp-daa nâa"),
  ("What are the requirements for this job?", "งานนี้ต้องการคุณสมบัติอะไรบ้าง", "ngaan níi tɔ̂ng-kaan khun-ná-sǒm-bàt à-rai bâang?"),
  ("I don't meet all the requirements, but I'll try anyway.", "ฉันมีคุณสมบัติไม่ครบทุกข้อ แต่ก็จะลองดู", "chǎn mii khun-ná-sǒm-bàt mâi khróp thúk khɔ̂ɔ, tɛ̀ɛ kɔ̂ɔ jà lɔɔng duu"),
  ("If you have a good reference, they'll hire you more easily.", "ถ้าคุณมีจดหมายรับรองดีๆ เขาจะรับคุณเข้าทำงานง่ายขึ้น", "thâa khun mii jòt-mǎai ráp-rɔɔng dii-dii, khǎo jà ráp khun khâo tham-ngaan ngâai khʉ̂n"),
  ("Don't forget to attach the reference to the application too!", "อย่าลืมแนบจดหมายรับรองไปกับใบสมัครด้วยนะ", "yàa lʉʉm nɛ̂ɛp jòt-mǎai ráp-rɔɔng pai kàp bai-sà-màk dûai ná!"),
  ("During the trial period the salary is a bit lower.", "ช่วงทดลองงาน เงินเดือนจะน้อยกว่านิดหน่อย", "chûang thót-lɔɔng-ngaan, ngən-dʉan jà nɔ́ɔi kwàa nít-nɔ̀i"),
  ("I'm looking for a full-time job near home.", "ฉันกำลังหางานเต็มเวลาที่อยู่ใกล้บ้าน", "chǎn kam-lang hǎa ngaan tem wee-laa thîi yùu klâi bâan"),
  ("My younger sister works part-time because she's still studying.", "น้องสาวผมทำงานพาร์ตไทม์เพราะยังเรียนอยู่", "nɔ́ɔng-sǎao phǒm tham-ngaan phâat-thaam phrɔ́ yang rian yùu"),
  ("They offered me a one-year fixed-term contract.", "เขาเสนอสัญญาจ้างระยะเวลาหนึ่งปีให้ฉัน", "khǎo sà-nə̌ə sǎn-yaa-jâang rá-yá-wee-laa nʉ̀ng pii hâi chǎn"),
  ("After you finish your studies, what field do you want to work in?", "พอเรียนจบแล้ว คุณอยากทำงานด้านไหน", "phɔɔ rian jòp lɛ́ɛo, khun yàak tham-ngaan dâan nǎi?"),
 ],
 "b1u3l2": [
  ("There are three important items on today's agenda.", "วาระการประชุมวันนี้มีเรื่องสำคัญสามเรื่อง", "waa-rá kaan prà-chum wan-níi mii rʉ̂ang sǎm-khan sǎam rʉ̂ang"),
  ("The new project will be presented at the next meeting.", "โครงการใหม่จะนำเสนอในการประชุมครั้งหน้า", "khroong-kaan mài jà nam-sà-nə̌ə nai kaan prà-chum khráng nâa"),
  ("Malee presented the monthly results in ten minutes.", "มาลีนำเสนอผลงานประจำเดือนภายในสิบนาที", "maa-lii nam-sà-nə̌ə phǒn-ngaan prà-jam dʉan phaai-nai sìp naa-thii"),
  ("Who proposed this idea first?", "ใครเป็นคนแรกที่เสนอความคิดนี้", "khrai pen khon rɛ̂ɛk thîi sà-nə̌ə khwaam-khít níi?"),
  ("At yesterday's meeting everyone approved our proposal.", "ในการประชุมเมื่อวาน ทุกคนเห็นชอบข้อเสนอของเรา", "nai kaan prà-chum mʉ̂a-waan, thúk khon hěn-chɔ̂ɔp khɔ̂ɔ-sà-nə̌ə khɔ̌ɔng rao"),
  ("If the budget isn't approved, the project will stop.", "ถ้างบประมาณไม่ผ่านการอนุมัติ โครงการก็จะหยุด", "thâa ngóp-prà-maan mâi phàan kaan à-nú-mát, khroong-kaan kɔ̂ɔ jà yùt"),
  ("We had to postpone the meeting to next week.", "เราต้องเลื่อนการประชุมไปสัปดาห์หน้า", "rao tɔ̂ng lʉ̂an kaan prà-chum pai sàp-daa nâa"),
  ("Come on, let's not put off important decisions again!", "เอาน่า เราอย่าเลื่อนการตัดสินใจเรื่องสำคัญออกไปอีกเลย", "ao nâa, rao yàa lʉ̂an kaan-tàt-sǐn-jai rʉ̂ang sǎm-khan ɔ̀ɔk pai ìik ləəi!"),
  ("At the end of the meeting, I'll send the minutes to everyone right away.", "พอประชุมเสร็จ ฉันจะส่งบันทึกการประชุมให้ทุกคนทันที", "phɔɔ prà-chum sèt, chǎn jà sòng ban-thʉ́k kaan prà-chum hâi thúk khon than-thii"),
  ("Our main goal is to finish the work on time.", "เป้าหมายหลักของเราคือทำงานให้เสร็จตามกำหนด", "pâo-mǎai làk khɔ̌ɔng rao khʉʉ tham-ngaan hâi sèt taam kam-nòt"),
  ("What will be given priority this year?", "ปีนี้จะให้ความสำคัญกับเรื่องอะไรเป็นอันดับแรก", "pii níi jà hâi khwaam-sǎm-khan kàp rʉ̂ang à-rai pen an-dàp rɛ̂ɛk?"),
  ("Before spending the budget, we need to set priorities.", "ก่อนใช้งบประมาณ เราต้องจัดลำดับความสำคัญก่อน", "kɔ̀ɔn chái ngóp-prà-maan, rao tɔ̂ng jàt lam-dàp khwaam-sǎm-khan kɔ̀ɔn"),
 ],
 "b1u3l3": [
  ("Ploy made a career very quickly at the bank.", "พลอยก้าวหน้าในอาชีพที่ธนาคารเร็วมาก", "phlɔɔi kâao-nâa nai aa-chîip thîi thá-naa-khaan reo mâak"),
  ("After two years she was promoted.", "สองปีต่อมาเธอได้เลื่อนตำแหน่ง", "sɔ̌ɔng pii tɔ̀ɔ maa thəə dâai lʉ̂an tam-nɛ̀ng"),
  ("If you work well, you'll be promoted soon.", "ถ้าคุณทำงานดี อีกไม่นานคุณก็จะได้เลื่อนตำแหน่ง", "thâa khun tham-ngaan dii, ìik mâi naan khun kɔ̂ɔ jà dâai lʉ̂an tam-nɛ̀ng"),
  ("Every year we do a week of training.", "ทุกปีเราจะมีการอบรมหนึ่งสัปดาห์", "thúk pii rao jà mii kaan òp-rom nʉ̀ng sàp-daa"),
  ("The retraining course is held online on Saturdays.", "หลักสูตรอบรมทักษะใหม่จัดทางออนไลน์ทุกวันเสาร์", "làk-sùut òp-rom thák-sà mài jàt thaang ɔɔn-lai thúk wan sǎo"),
  ("What skills do you need for this job?", "งานนี้ต้องใช้ทักษะอะไรบ้าง", "ngaan níi tɔ̂ng chái thák-sà à-rai bâang?"),
  ("In the new position I'll have more responsibility.", "ในตำแหน่งใหม่ ฉันจะมีความรับผิดชอบมากขึ้น", "nai tam-nɛ̀ng mài, chǎn jà mii khwaam-ráp-phìt-chɔ̂ɔp mâak khʉ̂n"),
  ("I've been waiting for a raise for a year.", "ผมรอขึ้นเงินเดือนมาปีหนึ่งแล้ว", "phǒm rɔɔ khʉ̂n ngən-dʉan maa pii nʉ̀ng lɛ́ɛo"),
  ("Somchai resigned because he found a new opportunity.", "สมชายลาออกเพราะเจอโอกาสใหม่", "sǒm-chaai laa-ɔ̀ɔk phrɔ́ jəə oo-kàat mài"),
  ("If they don't raise my salary, I'll resign.", "ถ้าเขาไม่ขึ้นเงินเดือนให้ ฉันจะลาออก", "thâa khǎo mâi khʉ̂n ngən-dʉan hâi, chǎn jà laa-ɔ̀ɔk"),
  ("Are you ready to move to another city for work?", "คุณพร้อมจะย้ายไปอยู่เมืองอื่นเพื่องานไหม", "khun phrɔ́ɔm jà yáai pai yùu mʉang ʉ̀ʉn phʉ̂a ngaan mǎi?"),
  ("An opportunity like this comes once in a lifetime.", "โอกาสแบบนี้มีแค่ครั้งเดียวในชีวิต", "oo-kàat bɛ̀ɛp níi mii khɛ̂ɛ khráng diao nai chii-wít"),
 ],
 "b1u3l4": [
  ("We have been working with Italian colleagues for many years.", "เราร่วมงานกับเพื่อนร่วมงานชาวอิตาลีมาหลายปีแล้ว", "rao rûam-ngaan kàp phʉ̂an-rûam-ngaan chaao ì-taa-lîi maa lǎai pii lɛ́ɛo"),
  ("A good boss can delegate tasks to others.", "หัวหน้าที่ดีรู้จักมอบหมายงานให้คนอื่น", "hǔa-nâa thîi dii rúu-jàk mɔ̂ɔp-mǎai ngaan hâi khon ʉ̀ʉn"),
  ("I gave this task to Somchai because I didn't have time.", "ฉันมอบงานนี้ให้สมชายเพราะไม่มีเวลา", "chǎn mɔ̂ɔp ngaan níi hâi sǒm-chaai phrɔ́ mâi mii wee-laa"),
  ("Thank you so much for your support at a difficult time.", "ขอบคุณมากที่คอยสนับสนุนในช่วงที่ลำบาก", "khɔ̀ɔp-khun mâak thîi khɔɔi sà-nàp-sà-nǔn nai chûang thîi lam-bàak"),
  ("The conflict between the two colleagues has been going on for a month.", "ความขัดแย้งระหว่างเพื่อนร่วมงานสองคนนี้ยืดเยื้อมาเดือนหนึ่งแล้ว", "khwaam-khàt-yɛ́ɛng rá-wàang phʉ̂an-rûam-ngaan sɔ̌ɔng khon níi yʉ̂ʉt-yʉ́a maa dʉan nʉ̀ng lɛ́ɛo"),
  ("It was just a misunderstanding, don't worry.", "แค่เข้าใจผิดกันเท่านั้นเอง ไม่ต้องห่วง", "khɛ̂ɛ khâo-jai phìt kan thâo-nán eeng, mâi tɔ̂ng hùang"),
  ("Could you clarify this point for me? (formal)", "คุณช่วยอธิบายประเด็นนี้ให้ชัดเจนหน่อยได้ไหมคะ", "khun chûai à-thí-baai prà-den níi hâi chát-jeen nɔ̀i dâai mǎi khá?"),
  ("Trust between colleagues is very important.", "ความไว้ใจระหว่างเพื่อนร่วมงานสำคัญมาก", "khwaam-wái-jai rá-wàang phʉ̂an-rûam-ngaan sǎm-khan mâak"),
  ("After that mistake, he lost the boss's trust.", "หลังจากความผิดพลาดครั้งนั้น เขาก็เสียความไว้ใจจากหัวหน้า", "lǎng-jàak khwaam-phìt-phlâat khráng nán, khǎo kɔ̂ɔ sǐa khwaam-wái-jai jàak hǔa-nâa"),
  ("Do you like the work environment in your new office?", "คุณชอบบรรยากาศในที่ทำงานใหม่ไหม", "khun chɔ̂ɔp ban-yaa-kàat nai thîi-tham-ngaan mài mǎi?"),
  ("If overwork goes on for a long time, a person gets sick.", "ถ้าทำงานหนักเกินไปนานๆ คนเราก็ป่วยได้", "thâa tham-ngaan nàk kəən pai naan-naan, khon rao kɔ̂ɔ pùai dâai"),
  ("How do you find a balance between work and family?", "คุณหาสมดุลระหว่างงานกับครอบครัวยังไง", "khun hǎa sǒm-dun rá-wàang ngaan kàp khrɔ̂ɔp-khrua yang-ngai?"),
 ],
 "b1u3x1": [
  ("I got two job offers, and I don't know which one to choose.", "ฉันได้ข้อเสนองานมาสองที่ ไม่รู้จะเลือกที่ไหนดี", "chǎn dâai khɔ̂ɔ-sà-nə̌ə ngaan maa sɔ̌ɔng thîi, mâi rúu jà lʉ̂ak thîi-nǎi dii"),
  ("How much experience is required for this vacancy?", "ตำแหน่งที่ว่างนี้ต้องมีประสบการณ์เท่าไร", "tam-nɛ̀ng thîi wâang níi tɔ̂ng mii prà-sòp-kaan thâo-rai?"),
  ("Write a short, clear cover letter.", "เขียนจดหมายแนะนำตัวให้สั้นและชัดเจน", "khǐan jòt-mǎai nɛ́-nam-tua hâi sân lɛ́ chát-jeen"),
  ("Yesterday they invited me to a second interview!", "เมื่อวานเขาเรียกฉันไปสัมภาษณ์รอบสอง", "mʉ̂a-waan khǎo rîak chǎn pai sǎm-phâat rɔ̂ɔp sɔ̌ɔng!"),
  ("After the first round of selection, ten candidates were left.", "หลังการคัดเลือกรอบแรก เหลือผู้สมัครสิบคน", "lǎng kaan khát-lʉ̂ak rɔ̂ɔp rɛ̂ɛk, lʉ̌a phûu-sà-màk sìp khon"),
  ("According to the boss, you're the ideal candidate.", "หัวหน้าบอกว่าคุณเป็นผู้สมัครที่เหมาะที่สุด", "hǔa-nâa bɔ̀ɔk wâa khun pen phûu-sà-màk thîi mɔ̀ thîi-sùt"),
  ("Don't get upset over one rejection!", "อย่าเสียใจเพราะถูกปฏิเสธแค่ครั้งเดียว", "yàa sǐa-jai phrɔ́ thùuk pà-tì-sèet khɛ̂ɛ khráng diao!"),
  ("I got hired! I start on Monday.", "ฉันได้งานแล้ว เริ่มวันจันทร์", "chǎn dâai ngaan lɛ́ɛo! rə̂əm wan jan"),
  ("Tomorrow I'll sign the contract and start working right away.", "พรุ่งนี้ผมจะเซ็นสัญญา แล้วเริ่มงานทันที", "phrûng-níi phǒm jà sen sǎn-yaa, lɛ́ɛo rə̂əm ngaan than-thii"),
  ("I did a six-month internship at a hotel.", "ฉันฝึกงานที่โรงแรมหกเดือน", "chǎn fʉ̀k-ngaan thîi roong-rɛɛm hòk dʉan"),
  ("I found this job through my network of contacts.", "ฉันได้งานนี้ผ่านเครือข่ายคนรู้จัก", "chǎn dâai ngaan níi phàan khrʉa-khàai khon rúu-jàk"),
  ("Before applying, update your resume.", "ก่อนสมัครงาน ปรับปรุงประวัติย่อให้เป็นปัจจุบันก่อน", "kɔ̀ɔn sà-màk ngaan, pràp-prung prà-wàt-yɔ̂ɔ hâi pen pàt-jù-ban kɔ̀ɔn"),
 ],
 "b1u3x2": [
  ("After a year, they gave me a permanent contract.", "หลังจากหนึ่งปี เขาก็บรรจุฉันเป็นพนักงานประจำ", "lǎng-jàak nʉ̀ng pii, khǎo kɔ̂ɔ ban-jù chǎn pen phá-nák-ngaan prà-jam"),
  ("Working part-time lets me study.", "การทำงานพาร์ตไทม์ทำให้ฉันมีเวลาเรียน", "kaan tham-ngaan phâat-thaam tham-hâi chǎn mii wee-laa rian"),
  ("Thanks to my flexible schedule, I can take the kids to school.", "เพราะเวลางานยืดหยุ่น ฉันเลยไปส่งลูกที่โรงเรียนได้", "phrɔ́ wee-laa ngaan yʉ̂ʉt-yùn, chǎn ləəi pai sòng lûuk thîi roong-rian dâai"),
  ("I don't want to work night shifts anymore.", "ผมไม่อยากทำงานกะดึกอีกแล้ว", "phǒm mâi yàak tham-ngaan kà dʉ̀k ìik lɛ́ɛo"),
  ("The difference between gross pay and take-home pay is big.", "เงินเดือนก่อนหักภาษีกับเงินที่ได้รับจริงต่างกันเยอะ", "ngən-dʉan kɔ̀ɔn hàk phaa-sǐi kàp ngən thîi dâi-ráp jing tàang kan yə́"),
  ("At the end of the year, everyone will be paid a bonus.", "ปลายปีทุกคนจะได้โบนัส", "plaai pii thúk khon jà dâai boo-nát"),
  ("In Italy, the extra annual payment is given in December.", "ที่อิตาลี เงินพิเศษประจำปีจะจ่ายในเดือนธันวาคม", "thîi ì-taa-lîi, ngən phí-sèet prà-jam pii jà jàai nai dʉan than-waa-khom"),
  ("Keep the receipts for the expense reimbursement.", "เก็บใบเสร็จไว้เพื่อเบิกค่าใช้จ่าย", "kèp bai-sèt wái phʉ̂a bə̀ək khâa-chái-jàai"),
  ("How many days of paid vacation do you get a year?", "คุณมีวันลาพักร้อนแบบได้เงินปีละกี่วัน", "khun mii wan laa phák-rɔ́ɔn bɛ̀ɛp dâai ngən pii lá kìi wan?"),
  ("Never leave a job without giving notice!", "อย่าลาออกจากงานโดยไม่แจ้งล่วงหน้าเด็ดขาด", "yàa laa-ɔ̀ɔk jàak ngaan dooi mâi jɛ̂ɛng lûang-nâa dèt-khàat!"),
  ("She handed in her resignation last week.", "เธอยื่นใบลาออกเมื่อสัปดาห์ที่แล้ว", "thəə yʉ̂ʉn bai-laa-ɔ̀ɔk mʉ̂a sàp-daa thîi lɛ́ɛo"),
  ("My grandfather retired at sixty.", "ปู่เกษียณตอนอายุหกสิบ", "pùu kà-sǐan tɔɔn aa-yú hòk-sìp"),
 ],
 "b1u3x3": [
  ("This job needs technical expertise and general skills.", "งานนี้ต้องใช้ความรู้ทางเทคนิคและทักษะทั่วไป", "ngaan níi tɔ̂ng chái khwaam-rúu thaang thék-ník lɛ́ thák-sà thûa-pai"),
  ("He has strong organizational skills; he organizes everything himself.", "เขามีทักษะการจัดการที่ดีมาก จัดการทุกอย่างเองหมด", "khǎo mii thák-sà kaan jàt-kaan thîi dii mâak, jàt-kaan thúk yàang eeng mòt"),
  ("Problem solving is my strong point.", "การแก้ปัญหาเป็นจุดแข็งของฉัน", "kaan kɛ̂ɛ pan-hǎa pen jùt-khɛ̌ng khɔ̌ɔng chǎn"),
  ("Critical thinking is also learned at school.", "การคิดอย่างมีวิจารณญาณก็เรียนรู้ได้ที่โรงเรียนด้วย", "kaan khít yàang mii wí-jaa-rá-ná-yaan kɔ̂ɔ rian-rúu dâai thîi roong-rian dûai"),
  ("Communication skills are needed in any job.", "ทักษะการสื่อสารจำเป็นในทุกงาน", "thák-sà kaan sʉ̀ʉ-sǎan jam-pen nai thúk ngaan"),
  ("This job requires precision and attention to detail.", "งานนี้ต้องการความแม่นยำและการใส่ใจในรายละเอียด", "ngaan níi tɔ̂ng-kaan khwaam-mɛ̂n-yam lɛ́ kaan sài-jai nai raai-lá-ìat"),
  ("Without team spirit, the project won't succeed.", "ถ้าไม่มีความสามัคคีในทีม โครงการก็ไม่สำเร็จ", "thâa mâi mii khwaam-sǎa-mák-khii nai thiim, khroong-kaan kɔ̂ɔ mâi sǎm-rèt"),
  ("Not everyone has leadership skills.", "ไม่ใช่ทุกคนที่มีภาวะผู้นำ", "mâi châi thúk khon thîi mii phaa-wá phûu-nam"),
  ("How do you manage your time when you have a lot of deadlines?", "เวลามีงานต้องส่งเยอะ คุณบริหารเวลายังไง", "wee-laa mii ngaan tɔ̂ng sòng yə́, khun bɔɔ-rí-hǎan wee-laa yang-ngai?"),
  ("Sports help me manage stress.", "กีฬาช่วยให้ฉันจัดการกับความเครียดได้", "kii-laa chûai hâi chǎn jàt-kaan kàp khwaam-khrîat dâai"),
  ("Can you do several things at the same time?", "คุณทำหลายอย่างพร้อมกันได้ไหม", "khun tham lǎai yàang phrɔ́ɔm kan dâai mǎi?"),
  ("I finished the computer course and got a certificate.", "ฉันเรียนหลักสูตรคอมพิวเตอร์จบและได้ใบประกาศ", "chǎn rian làk-sùut khɔm-phiu-tə̂ə jòp lɛ́ dâai bai-prà-kàat"),
 ],
 "b1u3x4": [
  ("The director called everyone to an urgent meeting.", "ผู้อำนวยการเรียกทุกคนเข้าประชุมด่วน", "phûu-am-nuai-kaan rîak thúk khon khâo prà-chum dùan"),
  ("Can you attend tomorrow's meeting? (formal)", "คุณเข้าร่วมประชุมพรุ่งนี้ได้ไหมครับ", "khun khâo-rûam prà-chum phrûng-níi dâai mǎi khráp?"),
  ("Who is moderating the debate today?", "วันนี้ใครเป็นผู้ดำเนินการอภิปราย", "wan-níi khrai pen phûu dam-nəən-kaan à-phí-praai?"),
  ("Please take notes, then we'll write the minutes of the meeting.", "ช่วยจดบันทึกไว้หน่อย แล้วเราจะเขียนรายงานการประชุมกัน", "chûai jòt-ban-thʉ́k wái nɔ̀i, lɛ́ɛo rao jà khǐan raai-ngaan kaan prà-chum kan"),
  ("Let's vote: who is in favor?", "มาลงคะแนนกันเถอะ ใครเห็นด้วยบ้าง", "maa long-khá-nɛɛn kan thə̀, khrai hěn-dûai bâang?"),
  ("Delaying the delivery will cost us dearly.", "การส่งงานล่าช้าจะทำให้เราเสียหายหนัก", "kaan sòng ngaan lâa-cháa jà tham-hâi rao sǐa-hǎai nàk"),
  ("At this stage of the project, we need more people.", "ในขั้นนี้ของโครงการ เราต้องการคนเพิ่ม", "nai khân níi khɔ̌ɔng khroong-kaan, rao tɔ̂ng-kaan khon phə̂əm"),
  ("The project manager is on vacation this week.", "ผู้จัดการโครงการลาพักร้อนสัปดาห์นี้", "phûu-jàt-kaan khroong-kaan laa phák-rɔ́ɔn sàp-daa níi"),
  ("We don't have enough resources to finish on time.", "เรามีทรัพยากรไม่พอที่จะทำให้เสร็จทันเวลา", "rao mii sáp-phá-yaa-kɔɔn mâi phɔɔ thîi jà tham hâi sèt than wee-laa"),
  ("The final report must be submitted by the end of the month.", "ต้องส่งรายงานฉบับสุดท้ายภายในสิ้นเดือน", "tɔ̂ng sòng raai-ngaan chà-bàp sùt-tháai phaai-nai sîn dʉan"),
  ("An unexpected obstacle came up, so we're running late.", "มีอุปสรรคที่ไม่คาดคิดเกิดขึ้น เราเลยล่าช้า", "mii ùp-pà-sàk thîi mâi khâat-khít kə̀ət-khʉ̂n, rao ləəi lâa-cháa"),
  ("What is the top priority this week?", "สัปดาห์นี้งานไหนสำคัญที่สุด", "sàp-daa níi ngaan nǎi sǎm-khan thîi-sùt?"),
 ],
 "b1u3x5": [
  ("The director always arrives at the office first.", "ผู้อำนวยการมาถึงที่ทำงานเป็นคนแรกเสมอ", "phûu-am-nuai-kaan maa thʉ̌ng thîi-tham-ngaan pen khon rɛ̂ɛk sà-mə̌ə"),
  ("When can I speak with the head of the department?", "ฉันจะคุยกับหัวหน้าแผนกได้เมื่อไร", "chǎn jà khui kàp hǔa-nâa phà-nɛ̀ɛk dâai mʉ̂a-rai?"),
  ("The supervisor checks everyone's work every day.", "ผู้ควบคุมงานตรวจงานของทุกคนทุกวัน", "phûu-khûap-khum-ngaan trùat ngaan khɔ̌ɔng thúk khon thúk wan"),
  ("More than two hundred employees work at our company.", "บริษัทของเรามีพนักงานมากกว่าสองร้อยคน", "bɔɔ-rí-sàt khɔ̌ɔng rao mii phá-nák-ngaan mâak kwàa sɔ̌ɔng rɔ́ɔi khon"),
  ("My assistant will send all the documents to you.", "ผู้ช่วยของผมจะส่งเอกสารทั้งหมดให้คุณ", "phûu-chûai khɔ̌ɔng phǒm jà sòng èek-kà-sǎan tháng-mòt hâi khun"),
  ("We brought in a consultant to solve the problem.", "เราจ้างที่ปรึกษามาช่วยแก้ปัญหา", "rao jâang thîi-prʉ̀k-sǎa maa chûai kɛ̂ɛ pan-hǎa"),
  ("You need to take these documents to the HR department.", "คุณต้องเอาเอกสารพวกนี้ไปส่งที่ฝ่ายบุคคล", "khun tɔ̂ng ao èek-kà-sǎan phûak-níi pai sòng thîi fàai bùk-khon"),
  ("Accounting pays salaries on the fifth of every month.", "ฝ่ายบัญชีจ่ายเงินเดือนทุกวันที่ห้าของเดือน", "fàai ban-chii jàai ngən-dʉan thúk wan thîi hâa khɔ̌ɔng dʉan"),
  ("My father has worked in production for thirty years.", "พ่อผมทำงานฝ่ายผลิตมาสามสิบปีแล้ว", "phɔ̂ɔ phǒm tham-ngaan fàai phà-lìt maa sǎam-sìp pii lɛ́ɛo"),
  ("If there's a problem, call customer service.", "ถ้ามีปัญหา โทรหาฝ่ายบริการลูกค้า", "thâa mii pan-hǎa, thoo hǎa fàai bɔɔ-rí-kaan lûuk-kháa"),
  ("The head office is in Bangkok, and the branches are in other cities.", "สำนักงานใหญ่อยู่ที่กรุงเทพ ส่วนสาขาอยู่ในเมืองอื่นๆ", "sǎm-nák-ngaan yài yùu thîi krung-thêep, sùan sǎa-khǎa yùu nai mʉang ʉ̀ʉn-ʉ̀ʉn"),
  ("Look at the organizational chart to see who does what.", "ดูแผนผังองค์กรเพื่อจะได้รู้ว่าใครทำอะไร", "duu phɛ̌ɛn-phǎng ong-kɔɔn phʉ̂a jà dâai rúu wâa khrai tham à-rai"),
 ],
 "b1u3x6": [
  ("Thanks to everyone's cooperation, we finished the work on time.", "ด้วยความร่วมมือของทุกคน เราทำงานเสร็จทันเวลา", "dûai khwaam-rûam-mʉʉ khɔ̌ɔng thúk khon, rao tham-ngaan sèt than wee-laa"),
  ("I never join in office gossip.", "ฉันไม่เคยไปร่วมนินทาในที่ทำงาน", "chǎn mâi khəəi pai rûam nin-thaa nai thîi-tham-ngaan"),
  ("Here promotions depend on connections, not on merit.", "ที่นี่การเลื่อนตำแหน่งขึ้นอยู่กับเส้นสาย ไม่ใช่ผลงาน", "thîi-nîi kaan lʉ̂an tam-nɛ̀ng khʉ̂n-yùu-kàp sên-sǎai, mâi châi phǒn-ngaan"),
  ("If you face pressure at work, contact the HR department. (plural)", "ถ้าพวกคุณถูกกดดันในที่ทำงาน ให้ติดต่อฝ่ายบุคคล", "thâa phûak-khun thùuk kòt-dan nai thîi-tham-ngaan, hâi tìt-tɔ̀ɔ fàai bùk-khon"),
  ("The boss doesn't know how to delegate; he does everything himself.", "หัวหน้าไม่รู้จักกระจายงาน ทำทุกอย่างเองหมด", "hǔa-nâa mâi rúu-jàk krà-jaai ngaan, tham thúk yàang eeng mòt"),
  ("Can I give you some feedback on your report?", "ขอให้ความเห็นเกี่ยวกับรายงานของคุณหน่อยได้ไหม", "khɔ̌ɔ hâi khwaam-hěn kìao-kàp raai-ngaan khɔ̌ɔng khun nɔ̀i dâai mǎi?"),
  ("Your contribution to this success is big.", "คุณมีส่วนสำคัญในความสำเร็จครั้งนี้", "khun mii sùan sǎm-khan nai khwaam-sǎm-rèt khráng níi"),
  ("I apologize for the delay in delivery.", "ขออภัยที่ส่งงานล่าช้า", "khɔ̌ɔ à-phai thîi sòng ngaan lâa-cháa"),
  ("Mediation is needed to resolve the conflict.", "ต้องมีการไกล่เกลี่ยเพื่อแก้ความขัดแย้ง", "tɔ̂ng mii kaan klài-klìa phʉ̂a kɛ̂ɛ khwaam-khàt-yɛ́ɛng"),
  ("How can we lift the team's morale?", "เราจะสร้างขวัญกำลังใจให้ทีมได้ยังไง", "rao jà sâang khwǎn-kam-lang-jai hâi thiim dâai yang-ngai?"),
  ("Tomorrow I have a performance review with the boss.", "พรุ่งนี้ฉันมีนัดประเมินผลงานกับหัวหน้า", "phrûng-níi chǎn mii nát prà-məən phǒn-ngaan kàp hǔa-nâa"),
  ("Without a common goal, a team won't go far.", "ถ้าไม่มีเป้าหมายร่วมกัน ทีมก็ไปได้ไม่ไกล", "thâa mâi mii pâo-mǎai rûam kan, thiim kɔ̂ɔ pai dâai mâi klai"),
 ],
 "b1u3x7": [
  ("This year my salary went up by ten percent!", "ปีนี้เงินเดือนฉันขึ้นสิบเปอร์เซ็นต์", "pii níi ngən-dʉan chǎn khʉ̂n sìp pəə-sen!"),
  ("Starting Monday, I'll be given a new task.", "ตั้งแต่วันจันทร์ ผมจะได้รับมอบหมายงานใหม่", "tâng-tɛ̀ɛ wan jan, phǒm jà dâi-ráp mɔ̂ɔp-mǎai ngaan mài"),
  ("I asked to be transferred to another branch.", "ฉันขอย้ายไปอยู่สาขาอื่น", "chǎn khɔ̌ɔ yáai pai yùu sǎa-khǎa ʉ̀ʉn"),
  ("At my first job, my mentor taught me everything.", "ที่งานแรกของฉัน พี่เลี้ยงสอนฉันทุกอย่าง", "thîi ngaan rɛ̂ɛk khɔ̌ɔng chǎn, phîi-líang sɔ̌ɔn chǎn thúk yàang"),
  ("What is your career goal for the next five years?", "เป้าหมายในอาชีพของคุณในอีกห้าปีข้างหน้าคืออะไร", "pâo-mǎai nai aa-chîip khɔ̌ɔng khun nai ìik hâa pii khâang-nâa khʉʉ à-rai?"),
  ("At forty, she changed fields and became a cook.", "ตอนอายุสี่สิบ เธอเปลี่ยนสายงานไปเป็นแม่ครัว", "tɔɔn aa-yú sìi-sìp, thəə plìan sǎai-ngaan pai pen mɛ̂ɛ-khrua"),
  ("One day I want to start my own business.", "สักวันหนึ่งผมอยากเปิดธุรกิจของตัวเอง", "sàk wan nʉ̀ng phǒm yàak pə̀ət thú-rá-kìt khɔ̌ɔng tua-eeng"),
  ("Thanks to remote work, I don't lose time on the road.", "เพราะได้ทำงานจากที่บ้าน ฉันเลยไม่ต้องเสียเวลาบนถนน", "phrɔ́ dâai tham-ngaan jàak thîi bâan, chǎn ləəi mâi tɔ̂ng sǐa wee-laa bon thà-nǒn"),
  ("Job satisfaction doesn't depend only on money.", "ความพึงพอใจในงานไม่ได้ขึ้นอยู่กับเงินอย่างเดียว", "khwaam-phʉng-phɔɔ-jai nai ngaan mâi dâai khʉ̂n-yùu-kàp ngən yàang diao"),
  ("Because of work stress, I can't sleep well.", "เพราะเครียดเรื่องงาน ฉันเลยนอนไม่ค่อยหลับ", "phrɔ́ khrîat rʉ̂ang ngaan, chǎn ləəi nɔɔn mâi khɔ̂i làp"),
  ("Is it hard to start again after a career break?", "หลังจากหยุดทำงานไปพักหนึ่ง การกลับมาเริ่มใหม่ยากไหม", "lǎng-jàak yùt tham-ngaan pai phák nʉ̀ng, kaan klàp maa rə̂əm mài yâak mǎi?"),
  ("Moving to Chiang Mai was a new beginning for me.", "การย้ายไปเชียงใหม่เป็นการเริ่มต้นใหม่สำหรับฉัน", "kaan yáai pai chiang-mài pen kaan rə̂əm-tôn mài sǎm-ràp chǎn"),
 ],
 "b1u3x8": [
  ("This month the workload has increased a lot.", "เดือนนี้ปริมาณงานเพิ่มขึ้นมาก", "dʉan níi pà-rí-maan ngaan phə̂əm khʉ̂n mâak"),
  ("With such tight deadlines, I can't do everything.", "กำหนดส่งกระชั้นขนาดนี้ ฉันทำทุกอย่างไม่ทันหรอก", "kam-nòt sòng krà-chán khà-nàat níi, chǎn tham thúk yàang mâi than rɔ̀ɔk"),
  ("I won't agree to unpaid overtime anymore.", "ผมจะไม่ยอมทำงานล่วงเวลาโดยไม่ได้เงินอีกแล้ว", "phǒm jà mâi yɔɔm tham-ngaan lûang-wee-laa dooi mâi dâai ngən ìik lɛ́ɛo"),
  ("According to the doctor, it's chronic fatigue.", "หมอบอกว่าเป็นอาการอ่อนเพลียเรื้อรัง", "mɔ̌ɔ bɔ̀ɔk wâa pen aa-kaan ɔ̀ɔn-phlia rʉ́a-rang"),
  ("He made a serious mistake and got a reprimand.", "เขาทำผิดร้ายแรงและถูกตักเตือน", "khǎo tham phìt ráai-rɛɛng lɛ́ thùuk tàk-tʉan"),
  ("If this happens again, the company will take action.", "ถ้าเกิดเรื่องนี้ขึ้นอีก บริษัทจะดำเนินการ", "thâa kə̀ət rʉ̂ang níi khʉ̂n ìik, bɔɔ-rí-sàt jà dam-nəən-kaan"),
  ("Explain the situation calmly, without rushing.", "อธิบายสถานการณ์ใจเย็นๆ ไม่ต้องรีบ", "à-thí-baai sà-thǎa-ná-kaan jai-yen-yen, mâi tɔ̂ng rîip"),
  ("Don't be afraid to ask colleagues for support.", "อย่ากลัวที่จะขอความช่วยเหลือจากเพื่อนร่วมงาน", "yàa klua thîi jà khɔ̌ɔ khwaam-chûai-lʉ̌a jàak phʉ̂an-rûam-ngaan"),
  ("Did you ask the boss to cut your working hours?", "คุณขอให้หัวหน้าลดชั่วโมงทำงานของคุณหรือยัง", "khun khɔ̌ɔ hâi hǔa-nâa lót chûa-moong tham-ngaan khɔ̌ɔng khun rʉ̌ʉ yang?"),
  ("Even on vacation I can't switch off from work.", "แม้แต่ตอนพักร้อน ฉันก็ยังเลิกคิดเรื่องงานไม่ได้", "mɛ́ɛ-tɛ̀ɛ tɔɔn phák-rɔ́ɔn, chǎn kɔ̂ɔ yang lə̂ək khít rʉ̂ang ngaan mâi dâai"),
  ("Before resigning, consider all the alternatives.", "ก่อนจะลาออก ลองพิจารณาทางเลือกอื่นทั้งหมดก่อน", "kɔ̀ɔn jà laa-ɔ̀ɔk, lɔɔng phí-jaa-rá-naa thaang-lʉ̂ak ʉ̀ʉn tháng-mòt kɔ̀ɔn"),
  ("When is your last working day here?", "วันทำงานวันสุดท้ายของคุณที่นี่คือวันไหน", "wan tham-ngaan wan sùt-tháai khɔ̌ɔng khun thîi-nîi khʉʉ wan nǎi?"),
 ],
}
